cat > /tmp/gate-check.mjs <<'EOF'
import assert from "node:assert/strict";
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/knock-inv-g2-2/bot.mjs";
const u = { id: "u1", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const d = (s) => new Date(s);
let g = createPushGate();
// Tokyo = UTC+9. 12:00 JST = 03:00Z
assert.deepEqual(g.attempt(u, d("2026-03-10T03:00:00Z")), { allowed: true, reason: null });
// 23:00 JST quiet, 06:59 JST quiet, 07:00 JST ok, 22:00 quiet
assert.equal(g.attempt(u, d("2026-03-10T14:00:00Z")).reason, "quiet_hours"); // 23:00
assert.equal(g.attempt(u, d("2026-03-10T21:59:00Z")).reason, "quiet_hours"); // 06:59 next day
assert.equal(g.attempt(u, d("2026-03-10T13:00:00Z")).reason, "quiet_hours"); // 22:00
// cap: 2 more allowed, 4th blocked; quiet attempts not counted
assert.equal(g.attempt(u, d("2026-03-10T04:00:00Z")).allowed, true);
assert.equal(g.attempt(u, d("2026-03-10T05:00:00Z")).allowed, true);
assert.equal(g.attempt(u, d("2026-03-10T06:00:00Z")).reason, "daily_cap_reached");
// next local day (JST midnight = 15:00Z) resets; 07:00 JST ok
assert.equal(g.attempt(u, d("2026-03-10T22:00:00Z")).allowed, true); // 07:00 JST Mar 11
// local day, not UTC: 23:30Z Mar10 = 08:30 JST Mar 11 same local day as above
g = createPushGate();
const la = { id: "u2", timeZone: "America/Los_Angeles", quietStart: "22:00", quietEnd: "07:00", dailyCap: 1 };
assert.equal(g.attempt(la, d("2026-03-10T03:00:00Z")).allowed, true); // Mar 9 20:00 PDT? (PDT since Mar 8) 
assert.equal(g.attempt(la, d("2026-03-10T05:00:00Z")).reason, "quiet_hours"); // 22:00 PDT
assert.equal(g.attempt(la, d("2026-03-10T06:30:00Z")).reason, "quiet_hours");
// 20:00 local Mar 9 sent; 23:30Z Mar 9 = 16:30 Mar 9 local -> cap reached (same local day though UTC day differs from sent)
assert.equal(g.attempt(la, d("2026-03-09T23:30:00Z")).allowed, true); // 16:30 Mar 9 first of local day
assert.equal(g.attempt(la, d("2026-03-10T03:30:00Z")).reason, "daily_cap_reached"); // 20:30 Mar 9
assert.equal(g.attempt(la, d("2026-03-10T15:00:00Z")).allowed, true); // 08:00 Mar 10
// independent gates & per-call settings
const g2 = createPushGate();
assert.equal(g2.attempt(la, d("2026-03-10T15:00:00Z")).allowed, true);
assert.equal(g2.attempt({ ...la, dailyCap: 0 }, d("2026-03-10T16:00:00Z")).reason, "daily_cap_reached");
assert.equal(g2.attempt({ ...la, dailyCap: 5 }, d("2026-03-10T16:00:00Z")).allowed, true);
// same-day quiet window (13:00-15:00), equal start/end, invalid input
const day = { id: "u3", timeZone: "UTC", quietStart: "13:00", quietEnd: "15:00", dailyCap: 9 };
assert.equal(createPushGate().attempt(day, d("2026-01-01T14:00:00Z")).reason, "quiet_hours");
assert.equal(createPushGate().attempt(day, d("2026-01-01T15:00:00Z")).allowed, true);
assert.equal(createPushGate().attempt({ ...day, timeZone: "Nope/Zone" }, d("2026-01-01T15:00:00Z")).reason, "invalid_user_settings");
assert.equal(createPushGate().attempt(day, new Date("x")).reason, "invalid_time");
// DST day (US fall back Nov 1 2026): local midnight handling
const ny = { id: "u4", timeZone: "America/New_York", quietStart: "22:00", quietEnd: "07:00", dailyCap: 2 };
const g3 = createPushGate();
assert.equal(g3.attempt(ny, d("2026-11-01T14:00:00Z")).allowed, true);  // 09:00 EST
assert.equal(g3.attempt(ny, d("2026-11-01T15:00:00Z")).allowed, true);
assert.equal(g3.attempt(ny, d("2026-11-02T04:30:00Z")).reason, "quiet_hours"); // 23:30 EST
assert.equal(g3.attempt(ny, d("2026-11-02T13:00:00Z")).allowed, true); // Nov 2 08:00
console.log("all ok");
EOF
